+		if strings.Contains(line, "process_sessions.1") && strings.Contains(line, "x") {
+			foundSubError = true
+			break
+		}
+	}
+	if !foundSubError {
+		t.Errorf("output missing error marker on process_sessions.1:\n%s", out)
+	}
