  60→+// traceStep represents a single timed step within a trace span.
  61→+// Group steps (from nested spans) have SubSteps with 0-based iteration numbering.
  62→+type traceStep struct {
  63→+	Name       string
  64→+	DurationMs int64
  65→+	Error      bool
  66→+	SubSteps   []traceStep
  67→+}
  68→+
  69→+// traceEntry represents a parsed performance trace log entry.
  70→+type traceEntry struct {
  71→+	Op         string
  72→+	DurationMs int64
  73→+	Error      bool
  74→+	Time       time.Time
  75→+	Steps      []traceStep
  76→+}
  77→+
  78→+// parseTraceEntry parses a JSON log line into a traceEntry.
  79→+// Returns nil if the line is not valid JSON or is not a trace entry (msg != "perf").
  80→+func parseTraceEntry(line string) *traceEntry {
  81→+	var raw map[string]json.RawMessage
  82→+	if err := json.Unmarshal([]byte(line), &raw); err != nil {
  83→+		return nil
  84→+	}
  85→+
  86→+	// Check that msg == "perf"
  87→+	var msg string
  88→+	if msgRaw, ok := raw["msg"]; !ok {
  89→+		return nil
  90→+	} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
  91→+		return nil
  92→+	}
  93→+
  94→+	entry := &traceEntry{}
  95→+
  96→+	// Best-effort field extraction: missing or mistyped fields keep their
  97→+	// zero values rather than discarding the entire entry.
  98→+	if opRaw, ok := raw["op"]; ok {
  99→+		_ = json.Unmarshal(opRaw, &entry.Op)
 100→+	}
 101→+	if dRaw, ok := raw["duration_ms"]; ok {
 102→+		_ = json.Unmarshal(dRaw, &entry.DurationMs)
 103→+	}
 104→+	if errRaw, ok := raw["error"]; ok {
 105→+		_ = json.Unmarshal(errRaw, &entry.Error)
 106→+	}
 107→+
 108→+	// Extract time
 109→+	if tRaw, ok := raw["time"]; ok {
 110→+		var ts string
 111→+		if err := json.Unmarshal(tRaw, &ts); err == nil {
 112→+			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
 113→+				entry.Time = parsed
 114→+			}
 115→+		}
 116→+	}
 117→+
 118→+	// Extract steps by finding keys matching "steps.*_ms"
 119→+	stepDurations := make(map[string]int64)
 120→+	stepErrors := make(map[string]bool)
 121→+
 122→+	for key, val := range raw {
 123→+		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
 124→+			name := strings.TrimPrefix(key, "steps.")
 125→+			name = strings.TrimSuffix(name, "_ms")
 126→+
 127→+			var ms int64
 128→+			if err := json.Unmarshal(val, &ms); err == nil {
 129→+				stepDurations[name] = ms
 130→+			}
 131→+		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
 132→+			name := strings.TrimPrefix(key, "steps.")
 133→+			name = strings.TrimSuffix(name, "_err")
 134→+
 135→+			var errFlag bool
 136→+			if err := json.Unmarshal(val, &errFlag); err == nil {
 137→+				stepErrors[name] = errFlag
 138→+			}
 139→+		}
 140→+	}
 141→+
 142→+	// Separate parent steps from sub-steps.
 143→+	// A key like "foo.0" is a sub-step of "foo" if "foo" also exists as a parent
 144→+	// and the last segment is a non-negative integer.
 145→+	subStepDurations := make(map[string]map[int]int64) // parent -> index -> ms
 146→+	subStepErrors := make(map[string]map[int]bool)     // parent -> index -> err
 147→+	parentStepDurations := make(map[string]int64)
 148→+	parentStepErrors := make(map[string]bool)
 149→+
 150→+	for name, ms := range stepDurations {
 151→+		if parent, idx, ok := parseSubStepKey(name, stepDurations); ok {
 152→+			if subStepDurations[parent] == nil {
 153→+				subStepDurations[parent] = make(map[int]int64)
 154→+			}
 155→+			subStepDurations[parent][idx] = ms
 156→+			if stepErrors[name] {
 157→+				if subStepErrors[parent] == nil {
 158→+					subStepErrors[parent] = make(map[int]bool)
 159→+				}
 160→+				subStepErrors[parent][idx] = true
 161→+			}
 162→+		} else {
 163→+			parentStepDurations[name] = ms
 164→+			parentStepErrors[name] = stepErrors[name]
 165→+		}
 166→+	}
 167→+
 168→+	// Build steps slice sorted alphabetically by name
 169→+	steps := make([]traceStep, 0, len(parentStepDurations))
 170→+	for name, ms := range parentStepDurations {
 171→+		step := traceStep{
 172→+			Name:       name,
 173→+			DurationMs: ms,
 174→+			Error:      parentStepErrors[name],
 175→+		}
 176→+
 177→+		// Attach sub-steps if any, sorted by numeric index
 178→+		if subs, ok := subStepDurations[name]; ok {
 179→+			indices := make([]int, 0, len(subs))
 180→+			for idx := range subs {
 181→+				indices = append(indices, idx)
 182→+			}
 183→+			sort.Ints(indices)
 184→+
 185→+			subList := make([]traceStep, 0, len(subs))
 186→+			for _, idx := range indices {
 187→+				subList = append(subList, traceStep{
 188→+					Name:       fmt.Sprintf("%s.%d", name, idx),
 189→+					DurationMs: subs[idx],
 190→+					Error:      subStepErrors[name][idx],
 191→+				})
 192→+			}
 193→+			step.SubSteps = subList
 194→+		}
 195→+
 196→+		steps = append(steps, step)
 197→+	}
 198→+	sort.Slice(steps, func(i, j int) bool {
 199→+		return steps[i].Name < steps[j].Name
 200→+	})
 201→+
 202→+	entry.Steps = steps
 203→+
 204→+	return entry
 205→+}
 206→+
 207→+// parseSubStepKey checks if a step name like "foo.0" is a sub-step of "foo".
 208→+// Returns the parent name, index, and true if it is a sub-step.
 209→+// A name is a sub-step if: the last segment after the final "." is a non-negative
 210→+// integer AND the parent name exists in allSteps.
 211→+func parseSubStepKey(name string, allSteps map[string]int64) (string, int, bool) {
 212→+	lastDot := strings.LastIndex(name, ".")
 213→+	if lastDot < 0 {
 214→+		return "", 0, false
 215→+	}
 216→+	parent := name[:lastDot]
 217→+	suffix := name[lastDot+1:]
 218→+	idx, err := strconv.Atoi(suffix)
 219→+	if err != nil || idx < 0 {
 220→+		return "", 0, false
 221→+	}
 222→+	if _, exists := allSteps[parent]; !exists {
 223→+		return "", 0, false
 224→+	}
 225→+	return parent, idx, true
 226→+}
