 228→+// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
 229→+// ordered newest first. If hookFilter is non-empty, only entries with a matching
 230→+// Op field are included.
 231→+func collectTraceEntries(logFile string, last int, hookFilter string) ([]traceEntry, error) {
 232→+	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
 233→+	if err != nil {
 234→+		if errors.Is(err, os.ErrNotExist) {
 235→+			return nil, nil
 236→+		}
 237→+		return nil, fmt.Errorf("opening log file: %w", err)
 238→+	}
 239→+	defer f.Close()
 240→+
 241→+	var entries []traceEntry
 242→+
 243→+	scanner := bufio.NewScanner(f)
 244→+	scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 1024*1024) // allow up to 1MB lines in shared log file
 245→+	for scanner.Scan() {
 246→+		entry := parseTraceEntry(scanner.Text())
 247→+		if entry == nil {
 248→+			continue
 249→+		}
 250→+		if hookFilter != "" && entry.Op != hookFilter {
 251→+			continue
 252→+		}
 253→+		entries = append(entries, *entry)
 254→+	}
 255→+
 256→+	if err := scanner.Err(); err != nil {
 257→+		return nil, fmt.Errorf("reading log file: %w", err)
 258→+	}
 259→+
 260→+	// Take the last N entries
 261→+	if len(entries) > last {
 262→+		entries = entries[len(entries)-last:]
 263→+	}
 264→+
 265→+	// Reverse so newest entries are first
 266→+	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
 267→+		entries[i], entries[j] = entries[j], entries[i]
 268→+	}
 269→+
 270→+	return entries, nil
 271→+}
