 273→+// renderTraceEntries writes a formatted table of trace entries to w.
 274→+// If entries is empty, it prints a help message about enabling traces.
 275→+func renderTraceEntries(w io.Writer, entries []traceEntry) {
 276→+	if len(entries) == 0 {
 277→+		fmt.Fprintln(w, "No trace entries found.")
 278→+		fmt.Fprintln(w, `Traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
 279→+		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
 280→+		return
 281→+	}
 282→+
 283→+	for i, entry := range entries {
 284→+		if i > 0 {
 285→+			fmt.Fprintln(w)
 286→+		}
 287→+
 288→+		// Header line: op  duration  [timestamp]
 289→+		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
 290→+		if !entry.Time.IsZero() {
 291→+			header += "  " + entry.Time.Format(time.RFC3339)
 292→+		}
 293→+		fmt.Fprintln(w, header)
 294→+		fmt.Fprintln(w)
 295→+
 296→+		if len(entry.Steps) == 0 {
 297→+			continue
 298→+		}
 299→+
 300→+		// Compute max name display width (at least len("STEP")).
 301→+		// Sub-steps are indented 5 extra display columns relative to parent rows
 302→+		// ("    " + "├─ " = 7 display cols vs "  " = 2 display cols).
 303→+		const subExtraIndent = 5
 304→+		nameWidth := len("STEP")
 305→+		for _, s := range entry.Steps {
 306→+			if len(s.Name) > nameWidth {
 307→+				nameWidth = len(s.Name)
 308→+			}
 309→+			for _, sub := range s.SubSteps {
 310→+				if needed := len(sub.Name) + subExtraIndent; needed > nameWidth {
 311→+					nameWidth = needed
 312→+				}
 313→+			}
 314→+		}
 315→+
 316→+		// Column header
 317→+		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
 318→+
 319→+		// Step rows
 320→+		for _, s := range entry.Steps {
 321→+			dur := fmt.Sprintf("%dms", s.DurationMs)
 322→+			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
 323→+			if s.Error {
 324→+				line += "  x"
 325→+			}
 326→+			fmt.Fprintln(w, line)
 327→+
 328→+			// Sub-step rows with ASCII tree connectors.
 329→+			// Pad manually to avoid multi-byte UTF-8 box-drawing chars
 330→+			// (├─, └─) breaking Go's byte-based %-*s alignment.
 331→+			for i, sub := range s.SubSteps {
 332→+				connector := "├─"
 333→+				if i == len(s.SubSteps)-1 {
 334→+					connector = "└─"
 335→+				}
 336→+				subDur := fmt.Sprintf("%dms", sub.DurationMs)
 337→+				pad := nameWidth - subExtraIndent - len(sub.Name)
 338→+				if pad < 0 {
 339→+					pad = 0
 340→+				}
 341→+				subLine := fmt.Sprintf("    %s %s%s  %8s", connector, sub.Name, strings.Repeat(" ", pad), subDur)
 342→+				if sub.Error {
 343→+					subLine += "  x"
 344→+				}
 345→+				fmt.Fprintln(w, subLine)
 346→+			}
 347→+		}
 348→+	}
 349→+}
