 408→+	cmd.Flags().IntVar(&last, "last", 1, "Show last N hook invocations")
 409→+	cmd.Flags().StringVar(&hookFilter, "hook", "", "Filter by hook type (e.g. post-commit, prepare-commit-msg, pre-push)")
 410→+
 411→+	return cmd
 412→+}
