 932→+//	    doWork(iterCtx, item)
 933→+//	    iterSpan.End()
 934→+//	}
 935→+//	loop.End()
 936→+type LoopSpan struct {
 937→+	span *Span
 938→+}
 939→+
 940→+// StartLoop begins a new loop span. The returned context contains the loop span
 941→+// and should be passed to Iteration. Call loop.End() after the loop completes.
 942→+func StartLoop(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *LoopSpan) {
 943→+	ctx, s := Start(ctx, name, attrs...)
 944→+	return ctx, &LoopSpan{span: s}
 945→+}
