 947→+// Iteration creates a child span for a single loop iteration. The caller must
 948→+// call End() on the returned span when the iteration completes.
 949→+func (l *LoopSpan) Iteration(ctx context.Context) (context.Context, *Span) {
 950→+	return Start(ctx, l.span.name)
 951→+}
 952→+
 953→+// End completes the loop span, auto-ending any unended iteration children first
 954→+// so their durations are captured at loop-end time rather than deferring to the
 955→+// root span's End() (which may run much later).
 956→+func (l *LoopSpan) End() {
 957→+	for _, child := range l.span.children {
 958→+		if !child.ended {
 959→+			child.End()
 960→+		}
 961→+	}
 962→+	l.span.End()
 963→+}
