 15→
 16→// traceStep represents a single timed step within a trace span.
 17→// Group steps (from nested spans) have SubSteps with 0-based iteration numbering.
 18→type traceStep struct {
 19→	Name       string
 20→	DurationMs int64
 21→	Error      bool
 22→	SubSteps   []traceStep
 23→}
 24→
 25→// traceEntry represents a parsed performance trace log entry.
 26→type traceEntry struct {
 27→	Op         string
 28→	DurationMs int64
 29→	Error      bool
 30→	Time       time.Time
 31→	Steps      []traceStep
 32→}
 33→
 34→// parseTraceEntry parses a JSON log line into a traceEntry.
 35→// Returns nil if the line is not valid JSON or is not a trace entry (msg != "perf").
 36→func parseTraceEntry(line string) *traceEntry {
 37→	var raw map[string]json.RawMessage
 38→	if err := json.Unmarshal([]byte(line), &raw); err != nil {
 39→		return nil
 40→	}
 41→
 42→	// Check that msg == "perf"
 43→	var msg string
 44→	if msgRaw, ok := raw["msg"]; !ok {
 45→		return nil
 46→	} else if err := json.Unmarshal(msgRaw, &msg); err != nil || msg != "perf" {
 47→		return nil
 48→	}
 49→
 50→	entry := &traceEntry{}
 51→
 52→	// Best-effort field extraction: missing or mistyped fields keep their
 53→	// zero values rather than discarding the entire entry.
 54→	if opRaw, ok := raw["op"]; ok {
 55→		_ = json.Unmarshal(opRaw, &entry.Op)
 56→	}
 57→	if dRaw, ok := raw["duration_ms"]; ok {
 58→		_ = json.Unmarshal(dRaw, &entry.DurationMs)
 59→	}
 60→	if errRaw, ok := raw["error"]; ok {
 61→		_ = json.Unmarshal(errRaw, &entry.Error)
 62→	}
 63→
 64→	// Extract time
 65→	if tRaw, ok := raw["time"]; ok {
 66→		var ts string
 67→		if err := json.Unmarshal(tRaw, &ts); err == nil {
 68→			if parsed, err := time.Parse(time.RFC3339, ts); err == nil {
 69→				entry.Time = parsed
 70→			}
 71→		}
 72→	}
 73→
 74→	// Extract steps by finding keys matching "steps.*_ms"
 75→	stepDurations := make(map[string]int64)
 76→	stepErrors := make(map[string]bool)
 77→
 78→	for key, val := range raw {
 79→		if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_ms") {
 80→			name := strings.TrimPrefix(key, "steps.")
 81→			name = strings.TrimSuffix(name, "_ms")
 82→
 83→			var ms int64
 84→			if err := json.Unmarshal(val, &ms); err == nil {
 85→				stepDurations[name] = ms
 86→			}
 87→		} else if strings.HasPrefix(key, "steps.") && strings.HasSuffix(key, "_err") {
 88→			name := strings.TrimPrefix(key, "steps.")
 89→			name = strings.TrimSuffix(name, "_err")
 90→
 91→			var errFlag bool
 92→			if err := json.Unmarshal(val, &errFlag); err == nil {
 93→				stepErrors[name] = errFlag
 94→			}
 95→		}
 96→	}
 97→
 98→	// Separate parent steps from sub-steps.
 99→	// A key like "foo.0" is a sub-step of "foo" if "foo" also exists as a parent
100→	// and the last segment is a non-negative integer.
101→	subStepDurations := make(map[string]map[int]int64) // parent -> index -> ms
102→	subStepErrors := make(map[string]map[int]bool)     // parent -> index -> err
103→	parentStepDurations := make(map[string]int64)
104→	parentStepErrors := make(map[string]bool)
105→
106→	for name, ms := range stepDurations {
107→		if parent, idx, ok := parseSubStepKey(name, stepDurations); ok {
108→			if subStepDurations[parent] == nil {
109→				subStepDurations[parent] = make(map[int]int64)
110→			}
111→			subStepDurations[parent][idx] = ms
112→			if stepErrors[name] {
113→				if subStepErrors[parent] == nil {
114→					subStepErrors[parent] = make(map[int]bool)
115→				}
116→				subStepErrors[parent][idx] = true
117→			}
118→		} else {
119→			parentStepDurations[name] = ms
120→			parentStepErrors[name] = stepErrors[name]
121→		}
122→	}
123→
124→	// Build steps slice sorted alphabetically by name
125→	steps := make([]traceStep, 0, len(parentStepDurations))
126→	for name, ms := range parentStepDurations {
127→		step := traceStep{
128→			Name:       name,
129→			DurationMs: ms,
130→			Error:      parentStepErrors[name],
131→		}
132→
133→		// Attach sub-steps if any, sorted by numeric index
134→		if subs, ok := subStepDurations[name]; ok {
135→			indices := make([]int, 0, len(subs))
136→			for idx := range subs {
137→				indices = append(indices, idx)
138→			}
139→			sort.Ints(indices)
140→
141→			subList := make([]traceStep, 0, len(subs))
142→			for _, idx := range indices {
143→				subList = append(subList, traceStep{
144→					Name:       fmt.Sprintf("%s.%d", name, idx),
145→					DurationMs: subs[idx],
146→					Error:      subStepErrors[name][idx],
147→				})
148→			}
149→			step.SubSteps = subList
150→		}
151→
152→		steps = append(steps, step)
153→	}
154→	sort.Slice(steps, func(i, j int) bool {
155→		return steps[i].Name < steps[j].Name
156→	})
157→
158→	entry.Steps = steps
159→
160→	return entry
161→}
162→
163→// parseSubStepKey checks if a step name like "foo.0" is a sub-step of "foo".
164→// Returns the parent name, index, and true if it is a sub-step.
165→// A name is a sub-step if: the last segment after the final "." is a non-negative
166→// integer AND the parent name exists in allSteps.
167→func parseSubStepKey(name string, allSteps map[string]int64) (string, int, bool) {
168→	lastDot := strings.LastIndex(name, ".")
169→	if lastDot < 0 {
170→		return "", 0, false
171→	}
172→	parent := name[:lastDot]
173→	suffix := name[lastDot+1:]
174→	idx, err := strconv.Atoi(suffix)
175→	if err != nil || idx < 0 {
176→		return "", 0, false
177→	}
178→	if _, exists := allSteps[parent]; !exists {
179→		return "", 0, false
180→	}
181→	return parent, idx, true
182→}
