184→// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
185→// ordered newest first. If hookFilter is non-empty, only entries with a matching
186→// Op field are included.
187→func collectTraceEntries(logFile string, last int, hookFilter string) ([]traceEntry, error) {
188→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
189→	if err != nil {
190→		if errors.Is(err, os.ErrNotExist) {
191→			return nil, nil
192→		}
193→		return nil, fmt.Errorf("opening log file: %w", err)
194→	}
195→	defer f.Close()
196→
197→	var entries []traceEntry
198→
199→	scanner := bufio.NewScanner(f)
200→	scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 1024*1024) // allow up to 1MB lines in shared log file
201→	for scanner.Scan() {
202→		entry := parseTraceEntry(scanner.Text())
203→		if entry == nil {
204→			continue
205→		}
206→		if hookFilter != "" && entry.Op != hookFilter {
207→			continue
208→		}
209→		entries = append(entries, *entry)
210→	}
211→
212→	if err := scanner.Err(); err != nil {
213→		return nil, fmt.Errorf("reading log file: %w", err)
214→	}
215→
216→	// Take the last N entries
217→	if len(entries) > last {
218→		entries = entries[len(entries)-last:]
219→	}
220→
221→	// Reverse so newest entries are first
222→	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
223→		entries[i], entries[j] = entries[j], entries[i]
224→	}
225→
226→	return entries, nil
227→}
228→
229→// renderTraceEntries writes a formatted table of trace entries to w.
230→// If entries is empty, it prints a help message about enabling traces.
231→func renderTraceEntries(w io.Writer, entries []traceEntry) {
232→	if len(entries) == 0 {
233→		fmt.Fprintln(w, "No trace entries found.")
234→		fmt.Fprintln(w, `Traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
235→		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
236→		return
237→	}
238→
239→	for i, entry := range entries {
240→		if i > 0 {
241→			fmt.Fprintln(w)
242→		}
243→
244→		// Header line: op  duration  [timestamp]
245→		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
246→		if !entry.Time.IsZero() {
247→			header += "  " + entry.Time.Format(time.RFC3339)
248→		}
249→		fmt.Fprintln(w, header)
250→		fmt.Fprintln(w)
251→
252→		if len(entry.Steps) == 0 {
253→			continue
254→		}
255→
256→		// Compute max name display width (at least len("STEP")).
257→		// Sub-steps are indented 5 extra display columns relative to parent rows
258→		// ("    " + "├─ " = 7 display cols vs "  " = 2 display cols).
259→		const subExtraIndent = 5
260→		nameWidth := len("STEP")
261→		for _, s := range entry.Steps {
262→			if len(s.Name) > nameWidth {
263→				nameWidth = len(s.Name)
264→			}
265→			for _, sub := range s.SubSteps {
266→				if needed := len(sub.Name) + subExtraIndent; needed > nameWidth {
267→					nameWidth = needed
268→				}
269→			}
270→		}
271→
272→		// Column header
273→		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
274→
275→		// Step rows
276→		for _, s := range entry.Steps {
277→			dur := fmt.Sprintf("%dms", s.DurationMs)
278→			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
279→			if s.Error {
280→				line += "  x"
281→			}
282→			fmt.Fprintln(w, line)
283→
284→			// Sub-step rows with ASCII tree connectors.
285→			// Pad manually to avoid multi-byte UTF-8 box-drawing chars
286→			// (├─, └─) breaking Go's byte-based %-*s alignment.
287→			for i, sub := range s.SubSteps {
288→				connector := "├─"
289→				if i == len(s.SubSteps)-1 {
290→					connector = "└─"
291→				}
292→				subDur := fmt.Sprintf("%dms", sub.DurationMs)
293→				pad := nameWidth - subExtraIndent - len(sub.Name)
294→				if pad < 0 {
295→					pad = 0
296→				}
297→				subLine := fmt.Sprintf("    %s %s%s  %8s", connector, sub.Name, strings.Repeat(" ", pad), subDur)
298→				if sub.Error {
299→					subLine += "  x"
300→				}
301→				fmt.Fprintln(w, subLine)
302→			}
303→		}
304→	}
305→}
